-- Q02 · Segurança depois de instalar: deny-by-default, barreira, ACL final exata, só servidor, nada ligado, nada escrito.
-- A ACL final é auditada entrada a entrada (aclexplode): além do dono, só service_role com exatamente
-- SELECT/INSERT/UPDATE/DELETE (tabelas) ou EXECUTE (funções), sem GRANT OPTION, sem permissões de coluna.
-- Só leitura: um único SELECT. Resultado: uma linha por verificação. Se alguma
-- verificação falhar (ou der NULL), a consulta TERMINA EM ERRO com "REPROVADO: <id> obtido=<valor> | …".
WITH v2 AS (SELECT unnest(ARRAY['access_invite_attempts', 'access_invites', 'access_waitlist', 'account_access', 'admin_audit_logs', 'admin_broadcast_recipients', 'admin_broadcasts', 'admin_cost_settings', 'admin_messages', 'admin_mfa_required', 'ai_model_rates', 'alert_mutes', 'announcement_dismissals', 'app_settings', 'app_user_connection_aliases', 'app_user_connections', 'assessor_ai_logs', 'assessor_messages', 'assessor_nudges', 'assessor_quality_scores', 'assessor_reasoning_traces', 'assessor_tool_calls', 'assistant_golden_conversations', 'assistant_golden_runs', 'assistant_reflections', 'assistant_shadow_runs', 'assistant_trust_scores', 'assistant_user_corrections', 'autonomy_rules', 'billing_test_accounts', 'calendar_connections', 'calendar_event_links', 'calendar_sync_log', 'calendar_sync_state', 'channel_links', 'consultant_preferences', 'content_access_consents', 'conversation_locks', 'conversation_states', 'daily_digests', 'daily_priorities', 'dashboard_announcements', 'dashboard_login_tokens', 'deal_deadlines', 'email_connections', 'email_drafts', 'email_messages', 'email_threads', 'entity_tags', 'event_categories', 'feature_flag_users', 'feature_flags', 'file_categories', 'file_links', 'financial_movements', 'folder_items', 'folders', 'follow_ups', 'inbound_message_claims', 'interactions', 'invite_send_attempts', 'landing_page_visits', 'mentor_decisions', 'miscellaneous_items', 'opportunities', 'opportunity_events', 'opportunity_properties', 'pending_actions', 'people', 'person_phones', 'pilot_invite_deliveries', 'pilot_participants', 'pilots', 'plan_configs', 'proactive_daily_ledger', 'product_feedback', 'product_telemetry_events', 'product_updates', 'profiles', 'promo_codes', 'promo_redemptions', 'properties', 'property_categories', 'property_interests', 'property_marketing_activities', 'property_offers', 'prospecting_leads', 'reminders', 'routines', 'short_links', 'similar_listing_searches', 'stripe_webhook_events', 'subscription_events', 'support_sessions', 'tags', 'telegram_invites', 'telegram_link_tokens', 'telegram_pairings', 'uploaded_files', 'whatsapp_link_codes', 'whatsapp_proactive_tests', 'whatsapp_send_logs', 'whatsapp_template_bindings', 'whatsapp_template_rates']::text[]) AS nome),
t2 AS (SELECT c.oid, c.relname::text AS nome, c.relacl, c.relowner, c.relrowsecurity, c.relforcerowsecurity FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace JOIN v2 ON v2.nome = c.relname::text WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p')),
f2 AS (SELECT p.oid, p.proname::text AS nome, p.proacl, p.proowner, p.prosrc FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname::text = ANY (ARRAY['access_invites_pilot_guard', 'account_access_on_new_profile', 'audit_sensitive_write', 'claim_inbound_message', 'claim_pending_confirmation', 'consultant_preferences_track_opt_ins', 'consume_access_invite', 'content_access_consents_validate', 'conversation_states_touch', 'daily_digests_validate', 'effective_tier', 'email_drafts_validate', 'expire_beta_testers', 'is_admin', 'issue_pilot_invite', 'issue_referral_invite', 'mark_pending_presented', 'pending_actions_validate', 'people_touch_email_norm', 'pilot_participant_on_invite_used', 'pilot_participants_guard', 'plan_configs_validate', 'product_feedback_validate', 'product_updates_validate', 'profiles_restrict_self_update', 'profiles_validate_billing', 'purge_admin_audit_logs', 'release_conversation_lock', 'release_pending_confirmation', 'release_unsolicited_slot', 'reminders_sync_follow_up_id', 'reserve_unsolicited_slot', 'revoke_pilot_invite', 'set_updated_at', 'subscription_events_validate', 'text_norm', 'tier_at_least', 'try_acquire_conversation_lock']::text[])),
acl_t AS (SELECT t2.nome, coalesce((SELECT string_agg(g, ',' ORDER BY g COLLATE "C") FROM (SELECT CASE WHEN e.grantee = 0 THEN 'PUBLIC' ELSE pg_get_userbyid(e.grantee)::text END || ':' || e.privilege_type::text || ':' || e.is_grantable::text AS g FROM aclexplode(t2.relacl) e WHERE e.grantee <> t2.relowner) z), '') AS acl FROM t2),
acl_f AS (SELECT f2.nome, coalesce((SELECT string_agg(g, ',' ORDER BY g COLLATE "C") FROM (SELECT CASE WHEN e.grantee = 0 THEN 'PUBLIC' ELSE pg_get_userbyid(e.grantee)::text END || ':' || e.privilege_type::text || ':' || e.is_grantable::text AS g FROM aclexplode(f2.proacl) e WHERE e.grantee <> f2.proowner) z), '') AS acl FROM f2),
c(id, verificacao, ok, esperado, obtido) AS (
  SELECT 'Q02-01'::text, 'as 104 tabelas V2 existem'::text, ((SELECT count(*) FROM t2) = 104)::boolean, '104'::text, ((SELECT count(*) FROM t2)::text)::text
  UNION ALL SELECT 'Q02-02'::text, 'RLS ligado em todas as tabelas de public'::text, (NOT EXISTS (SELECT 1 FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND NOT c.relrowsecurity))::boolean, 'todas'::text, (coalesce((SELECT string_agg(c.relname::text, ',') FROM pg_class c JOIN pg_namespace n ON n.oid = c.relnamespace WHERE n.nspname = 'public' AND c.relkind IN ('r', 'p') AND NOT c.relrowsecurity), 'todas com RLS'))::text
  UNION ALL SELECT 'Q02-03'::text, 'barreira staging_gate_admin_tester em cada tabela V2 (RESTRICTIVE, ALL, anon+authenticated, has_staging_access(auth.uid()))'::text, ((SELECT count(DISTINCT p.tablename) FROM pg_policies p JOIN v2 ON v2.nome = p.tablename::text WHERE p.schemaname = 'public' AND p.policyname = 'staging_gate_admin_tester' AND p.permissive = 'RESTRICTIVE' AND p.cmd = 'ALL' AND p.roles = ARRAY['anon', 'authenticated']::name[] AND p.qual ~ '^\(?(public\.)?has_staging_access\(auth\.uid\(\)\)\)?$' AND p.with_check ~ '^\(?(public\.)?has_staging_access\(auth\.uid\(\)\)\)?$') = 104)::boolean, '104'::text, ((SELECT count(DISTINCT p.tablename) FROM pg_policies p JOIN v2 ON v2.nome = p.tablename::text WHERE p.schemaname = 'public' AND p.policyname = 'staging_gate_admin_tester' AND p.permissive = 'RESTRICTIVE' AND p.cmd = 'ALL' AND p.roles = ARRAY['anon', 'authenticated']::name[] AND p.qual ~ '^\(?(public\.)?has_staging_access\(auth\.uid\(\)\)\)?$' AND p.with_check ~ '^\(?(public\.)?has_staging_access\(auth\.uid\(\)\)\)?$')::text)::text
  UNION ALL SELECT 'Q02-04'::text, 'nenhuma outra política restritiva em public'::text, ((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND permissive = 'RESTRICTIVE') = 104)::boolean, '104'::text, ((SELECT count(*) FROM pg_policies WHERE schemaname = 'public' AND permissive = 'RESTRICTIVE')::text)::text
  UNION ALL SELECT 'Q02-05'::text, 'anon sem nenhum privilégio efetivo (tabela ou coluna) nas tabelas V2'::text, (NOT EXISTS (SELECT 1 FROM t2 WHERE has_table_privilege('anon', oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege('anon', oid, 'SELECT,INSERT,UPDATE,REFERENCES')))::boolean, 'nenhum'::text, (coalesce((SELECT string_agg(nome, ',') FROM t2 WHERE has_table_privilege('anon', oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege('anon', oid, 'SELECT,INSERT,UPDATE,REFERENCES')), 'nenhum'))::text
  UNION ALL SELECT 'Q02-06'::text, 'authenticated (sem papel, tester e admin) sem nenhum privilégio efetivo nas tabelas V2'::text, (NOT EXISTS (SELECT 1 FROM t2 WHERE has_table_privilege('authenticated', oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege('authenticated', oid, 'SELECT,INSERT,UPDATE,REFERENCES')))::boolean, 'nenhum'::text, (coalesce((SELECT string_agg(nome, ',') FROM t2 WHERE has_table_privilege('authenticated', oid, 'SELECT,INSERT,UPDATE,DELETE,TRUNCATE,REFERENCES,TRIGGER') OR has_any_column_privilege('authenticated', oid, 'SELECT,INSERT,UPDATE,REFERENCES')), 'nenhum'))::text
  UNION ALL SELECT 'Q02-07'::text, 'ACL final de cada tabela V2 = dono + exatamente service_role:DELETE:false,service_role:INSERT:false,service_role:SELECT:false,service_role:UPDATE:false'::text, (NOT EXISTS (SELECT 1 FROM acl_t WHERE acl <> 'service_role:DELETE:false,service_role:INSERT:false,service_role:SELECT:false,service_role:UPDATE:false') AND (SELECT count(*) FROM acl_t) = 104)::boolean, 'service_role:DELETE:false,service_role:INSERT:false,service_role:SELECT:false,service_role:UPDATE:false'::text, (coalesce((SELECT string_agg(nome || '=' || acl, ' ; ') FROM (SELECT nome, acl FROM acl_t WHERE acl <> 'service_role:DELETE:false,service_role:INSERT:false,service_role:SELECT:false,service_role:UPDATE:false' ORDER BY nome LIMIT 5) z), 'todas exatas'))::text
  UNION ALL SELECT 'Q02-08'::text, 'nenhuma permissão de coluna nas tabelas V2'::text, (NOT EXISTS (SELECT 1 FROM pg_attribute a JOIN t2 ON t2.oid = a.attrelid WHERE a.attacl IS NOT NULL))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(t2.nome || '.' || a.attname::text, ',') FROM pg_attribute a JOIN t2 ON t2.oid = a.attrelid WHERE a.attacl IS NOT NULL), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-09'::text, 'service_role: efetivamente SELECT/INSERT/UPDATE/DELETE e SEM TRUNCATE/REFERENCES/TRIGGER em todas as tabelas V2'::text, (NOT EXISTS (SELECT 1 FROM t2 WHERE NOT (has_table_privilege('service_role', oid, 'SELECT') AND has_table_privilege('service_role', oid, 'INSERT') AND has_table_privilege('service_role', oid, 'UPDATE') AND has_table_privilege('service_role', oid, 'DELETE')) OR has_table_privilege('service_role', oid, 'TRUNCATE') OR has_table_privilege('service_role', oid, 'REFERENCES') OR has_table_privilege('service_role', oid, 'TRIGGER')))::boolean, 'todas'::text, (coalesce((SELECT string_agg(nome, ',') FROM t2 WHERE NOT (has_table_privilege('service_role', oid, 'SELECT') AND has_table_privilege('service_role', oid, 'INSERT') AND has_table_privilege('service_role', oid, 'UPDATE') AND has_table_privilege('service_role', oid, 'DELETE')) OR has_table_privilege('service_role', oid, 'TRUNCATE') OR has_table_privilege('service_role', oid, 'REFERENCES') OR has_table_privilege('service_role', oid, 'TRIGGER')), 'todas'))::text
  UNION ALL SELECT 'Q02-10'::text, 'dono de todas as tabelas e funções V2: um único papel, que não é cliente nem servidor da API'::text, ((SELECT count(DISTINCT o) FROM (SELECT relowner AS o FROM t2 UNION ALL SELECT proowner FROM f2) z) = 1 AND NOT EXISTS (SELECT 1 FROM (SELECT relowner AS o FROM t2 UNION ALL SELECT proowner FROM f2) z WHERE pg_get_userbyid(o) IN ('anon', 'authenticated', 'service_role', 'authenticator')))::boolean, '1 dono'::text, ((SELECT string_agg(DISTINCT pg_get_userbyid(o)::text, ',') FROM (SELECT relowner AS o FROM t2 UNION ALL SELECT proowner FROM f2) z))::text
  UNION ALL SELECT 'Q02-11'::text, 'as 38 funções V2 existem'::text, ((SELECT count(*) FROM f2) = 38)::boolean, '38'::text, ((SELECT count(*) FROM f2)::text)::text
  UNION ALL SELECT 'Q02-12'::text, 'funções em quarentena NÃO existem (merge_accounts_apply, merge_accounts_preview, handle_new_user)'::text, (NOT EXISTS (SELECT 1 FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname::text = ANY (ARRAY['merge_accounts_apply', 'merge_accounts_preview', 'handle_new_user']::text[])))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(p.proname::text, ',') FROM pg_proc p JOIN pg_namespace n ON n.oid = p.pronamespace WHERE n.nspname = 'public' AND p.proname::text = ANY (ARRAY['merge_accounts_apply', 'merge_accounts_preview', 'handle_new_user']::text[])), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-13'::text, 'nenhuma função V2 escreve em user_roles ou staging_notes'::text, (NOT EXISTS (SELECT 1 FROM f2 WHERE prosrc ~* '(insert[[:space:]]+into|update|delete[[:space:]]+from|truncate|merge[[:space:]]+into)[[:space:]]+(only[[:space:]]+)?(public\.)?"?(user_roles|staging_notes)\y'))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(nome, ',') FROM f2 WHERE prosrc ~* '(insert[[:space:]]+into|update|delete[[:space:]]+from|truncate|merge[[:space:]]+into)[[:space:]]+(only[[:space:]]+)?(public\.)?"?(user_roles|staging_notes)\y'), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-14'::text, 'nenhuma função V2 descobre tabelas no catálogo para SQL dinâmico'::text, (NOT EXISTS (SELECT 1 FROM f2 WHERE prosrc ~* 'information_schema\.(columns|tables)|pg_catalog\.pg_(class|attribute|tables)' AND prosrc ~* 'format[[:space:]]*\([^;]*%I'))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(nome, ',') FROM f2 WHERE prosrc ~* 'information_schema\.(columns|tables)|pg_catalog\.pg_(class|attribute|tables)' AND prosrc ~* 'format[[:space:]]*\([^;]*%I'), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-15'::text, 'nenhuma função V2 executável por anon ou authenticated'::text, (NOT EXISTS (SELECT 1 FROM f2 WHERE has_function_privilege('anon', oid, 'EXECUTE') OR has_function_privilege('authenticated', oid, 'EXECUTE')))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(nome, ',') FROM f2 WHERE has_function_privilege('anon', oid, 'EXECUTE') OR has_function_privilege('authenticated', oid, 'EXECUTE')), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-16'::text, 'ACL final de cada função V2 = dono + exatamente service_role:EXECUTE:false (ACL nula conta como PUBLIC => falha)'::text, (NOT EXISTS (SELECT 1 FROM acl_f WHERE acl <> 'service_role:EXECUTE:false') AND (SELECT count(*) FROM acl_f) = 38)::boolean, 'service_role:EXECUTE:false'::text, (coalesce((SELECT string_agg(nome || '=' || acl, ' ; ') FROM (SELECT nome, acl FROM acl_f WHERE acl <> 'service_role:EXECUTE:false' ORDER BY nome LIMIT 5) z), 'todas exatas'))::text
  UNION ALL SELECT 'Q02-17'::text, 'nenhuma política permissiva em public para PUBLIC ou anon'::text, (NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'public' AND permissive = 'PERMISSIVE' AND (roles @> ARRAY['public']::name[] OR roles @> ARRAY['anon']::name[])))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(tablename || '.' || policyname, ',') FROM pg_policies WHERE schemaname = 'public' AND permissive = 'PERMISSIVE' AND (roles @> ARRAY['public']::name[] OR roles @> ARRAY['anon']::name[])), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-18'::text, 'storage: nenhuma política para assessor-files e o bucket não existe'::text, (NOT EXISTS (SELECT 1 FROM pg_policies WHERE schemaname = 'storage' AND (coalesce(qual, '') ILIKE '%assessor-files%' OR coalesce(with_check, '') ILIKE '%assessor-files%' OR policyname ILIKE 'assessor_files%')) AND NOT EXISTS (SELECT 1 FROM storage.buckets WHERE id = 'assessor-files'))::boolean, 'nada'::text, ((SELECT count(*) FROM pg_policies WHERE schemaname = 'storage' AND (coalesce(qual, '') ILIKE '%assessor-files%' OR coalesce(with_check, '') ILIKE '%assessor-files%' OR policyname ILIKE 'assessor_files%'))::text || ' políticas / ' || (SELECT count(*) FROM storage.buckets WHERE id = 'assessor-files')::text || ' bucket')::text
  UNION ALL SELECT 'Q02-19'::text, 'Realtime: nenhuma tabela V2 publicada'::text, (NOT EXISTS (SELECT 1 FROM pg_publication_tables pt JOIN v2 ON v2.nome = pt.tablename::text WHERE pt.schemaname = 'public'))::boolean, 'nenhuma'::text, (coalesce((SELECT string_agg(pt.pubname || ':' || pt.tablename, ',') FROM pg_publication_tables pt JOIN v2 ON v2.nome = pt.tablename::text WHERE pt.schemaname = 'public'), 'nenhuma'))::text
  UNION ALL SELECT 'Q02-20'::text, 'nenhum gatilho em auth.users nem em staging_notes/user_roles'::text, (NOT EXISTS (SELECT 1 FROM pg_trigger WHERE tgrelid IN ('auth.users'::regclass, 'public.user_roles'::regclass, 'public.staging_notes'::regclass) AND NOT tgisinternal))::boolean, 'nenhum'::text, (coalesce((SELECT string_agg(tgrelid::regclass::text || '.' || tgname::text, ',') FROM pg_trigger WHERE tgrelid IN ('auth.users'::regclass, 'public.user_roles'::regclass, 'public.staging_notes'::regclass) AND NOT tgisinternal), 'nenhum'))::text
  UNION ALL SELECT 'Q02-21'::text, 'chaves para auth.users em public: só profiles_id_fkey (V2) e user_roles_user_id_fkey (staging)'::text, (coalesce((SELECT string_agg(cl.relname::text || '.' || x.conname::text, ',' ORDER BY cl.relname, x.conname) FROM pg_constraint x JOIN pg_class cl ON cl.oid = x.conrelid JOIN pg_namespace n ON n.oid = cl.relnamespace WHERE n.nspname = 'public' AND x.contype = 'f' AND x.confrelid = 'auth.users'::regclass), '') = 'profiles.profiles_id_fkey,user_roles.user_roles_user_id_fkey')::boolean, 'profiles.profiles_id_fkey,user_roles.user_roles_user_id_fkey'::text, ((SELECT string_agg(cl.relname::text || '.' || x.conname::text, ',' ORDER BY cl.relname, x.conname) FROM pg_constraint x JOIN pg_class cl ON cl.oid = x.conrelid JOIN pg_namespace n ON n.oid = cl.relnamespace WHERE n.nspname = 'public' AND x.contype = 'f' AND x.confrelid = 'auth.users'::regclass))::text
  UNION ALL SELECT 'Q02-22'::text, 'zero linhas em TODAS as 104 tabelas V2 (sem seeds, sem interruptores, sem perfis, sem envios)'::text, ((SELECT sum((xpath('/row/c/text()', query_to_xml(format('select count(*) as c from public.%I', nome), false, true, '')))[1]::text::bigint) FROM t2) = 0)::boolean, '0'::text, ((SELECT sum((xpath('/row/c/text()', query_to_xml(format('select count(*) as c from public.%I', nome), false, true, '')))[1]::text::bigint)::text || ' linhas; não vazias: ' || coalesce(string_agg(nome, ',') FILTER (WHERE (xpath('/row/c/text()', query_to_xml(format('select count(*) as c from public.%I', nome), false, true, '')))[1]::text::bigint > 0), '-') FROM t2))::text
  UNION ALL SELECT 'Q02-23'::text, 'valores por omissão de envio/sincronização = false'::text, ((SELECT count(*) FROM pg_attribute a JOIN t2 c ON c.oid = a.attrelid JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE (c.nome || '.' || a.attname::text) = ANY (ARRAY['access_waitlist.notify', 'calendar_sync_state.enabled', 'consultant_preferences.morning_briefing_enabled', 'consultant_preferences.evening_wrap_enabled', 'consultant_preferences.evening_checkin_enabled', 'whatsapp_proactive_tests.forced']::text[]) AND pg_get_expr(d.adbin, d.adrelid) = 'false') = 6)::boolean, '6'::text, ((SELECT count(*) FROM pg_attribute a JOIN t2 c ON c.oid = a.attrelid JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE (c.nome || '.' || a.attname::text) = ANY (ARRAY['access_waitlist.notify', 'calendar_sync_state.enabled', 'consultant_preferences.morning_briefing_enabled', 'consultant_preferences.evening_wrap_enabled', 'consultant_preferences.evening_checkin_enabled', 'whatsapp_proactive_tests.forced']::text[]) AND pg_get_expr(d.adbin, d.adrelid) = 'false')::text)::text
  UNION ALL SELECT 'Q02-24'::text, 'colunas boolean com DEFAULT true = exatamente as previstas (nenhuma de envio)'::text, (coalesce((SELECT array_agg(k ORDER BY k COLLATE "C") FROM (SELECT c.nome || '.' || a.attname::text FROM pg_attribute a JOIN t2 c ON c.oid = a.attrelid JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE a.atttypid = 'boolean'::regtype AND pg_get_expr(d.adbin, d.adrelid) = 'true') a(k)), '{}') = ARRAY['assessor_ai_logs.success', 'assessor_reasoning_traces.success', 'assistant_golden_conversations.active', 'autonomy_rules.requires_confirmation', 'dashboard_announcements.active', 'product_updates.is_published', 'promo_codes.active', 'routines.active']::text[])::boolean, 'assessor_ai_logs.success,assessor_reasoning_traces.success,assistant_golden_conversations.active,autonomy_rules.requires_confirmation,dashboard_announcements.active,product_updates.is_published,promo_codes.active,routines.active'::text, ((SELECT string_agg(k, ',' ORDER BY k COLLATE "C") FROM (SELECT c.nome || '.' || a.attname::text FROM pg_attribute a JOIN t2 c ON c.oid = a.attrelid JOIN pg_attrdef d ON d.adrelid = a.attrelid AND d.adnum = a.attnum WHERE a.atttypid = 'boolean'::regtype AND pg_get_expr(d.adbin, d.adrelid) = 'true') a(k)))::text
  UNION ALL SELECT 'Q02-25'::text, 'nenhum papel V2 atribuído (consultant/support_admin/super_admin)'::text, (NOT EXISTS (SELECT 1 FROM public.user_roles WHERE role::text IN ('consultant', 'support_admin', 'super_admin')))::boolean, 'nenhum'::text, ((SELECT count(*) FROM public.user_roles WHERE role::text IN ('consultant', 'support_admin', 'super_admin'))::text)::text
  UNION ALL SELECT 'Q02-26'::text, 'unaccent instalada em extensions'::text, (EXISTS (SELECT 1 FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'unaccent' AND n.nspname = 'extensions'))::boolean, 'extensions'::text, (coalesce((SELECT n.nspname::text FROM pg_extension e JOIN pg_namespace n ON n.oid = e.extnamespace WHERE e.extname = 'unaccent'), 'não instalada'))::text
  UNION ALL SELECT 'Q02-27'::text, 'agendador: nenhuma tarefa chama funções V2'::text, (CASE WHEN to_regclass('cron.job') IS NULL THEN true ELSE (xpath('/row/c/text()', query_to_xml('select count(*) as c from cron.job where command ~* ' || quote_literal('access_invites_pilot_guard|account_access_on_new_profile|audit_sensitive_write|claim_inbound_message|claim_pending_confirmation|consultant_preferences_track_opt_ins|consume_access_invite|content_access_consents_validate|conversation_states_touch|daily_digests_validate|effective_tier|email_drafts_validate|expire_beta_testers|is_admin|issue_pilot_invite|issue_referral_invite|mark_pending_presented|pending_actions_validate|people_touch_email_norm|pilot_participant_on_invite_used|pilot_participants_guard|plan_configs_validate|product_feedback_validate|product_updates_validate|profiles_restrict_self_update|profiles_validate_billing|purge_admin_audit_logs|release_conversation_lock|release_pending_confirmation|release_unsolicited_slot|reminders_sync_follow_up_id|reserve_unsolicited_slot|revoke_pilot_invite|set_updated_at|subscription_events_validate|text_norm|tier_at_least|try_acquire_conversation_lock'), false, true, '')))[1]::text::int = 0 END)::boolean, '0'::text, (CASE WHEN to_regclass('cron.job') IS NULL THEN 'sem agendador' ELSE (xpath('/row/c/text()', query_to_xml('select count(*) as c from cron.job where command ~* ' || quote_literal('access_invites_pilot_guard|account_access_on_new_profile|audit_sensitive_write|claim_inbound_message|claim_pending_confirmation|consultant_preferences_track_opt_ins|consume_access_invite|content_access_consents_validate|conversation_states_touch|daily_digests_validate|effective_tier|email_drafts_validate|expire_beta_testers|is_admin|issue_pilot_invite|issue_referral_invite|mark_pending_presented|pending_actions_validate|people_touch_email_norm|pilot_participant_on_invite_used|pilot_participants_guard|plan_configs_validate|product_feedback_validate|product_updates_validate|profiles_restrict_self_update|profiles_validate_billing|purge_admin_audit_logs|release_conversation_lock|release_pending_confirmation|release_unsolicited_slot|reminders_sync_follow_up_id|reserve_unsolicited_slot|revoke_pilot_invite|set_updated_at|subscription_events_validate|text_norm|tier_at_least|try_acquire_conversation_lock'), false, true, '')))[1]::text END)::text
),
v AS (SELECT count(*) AS n, string_agg(id || ' obtido=' || left(coalesce(obtido, 'NULL'), 160), ' | ' ORDER BY id) FILTER (WHERE ok IS NOT TRUE) AS falhas FROM c)
SELECT c.id, c.verificacao, CASE WHEN c.ok IS TRUE THEN 'OK' ELSE 'FALHA' END AS estado, c.esperado, c.obtido,
       CASE WHEN v.n <> 27 THEN ('VEREDITO INVÁLIDO: ' || v.n::text || ' verificações')::int::text
            WHEN v.falhas IS NULL THEN 'APROVADO'
            ELSE ('REPROVADO: ' || v.falhas)::int::text END AS veredito
  FROM c CROSS JOIN v ORDER BY c.id;
